\label{thm:two-channel}
Let $H_l\in\mathcal{B}_n$ for all $l$. Let $u_l:=\mathcal F_l(h^{\mathrm{pre}}_l x_l)$ be the block output, and let $\bar h_l:=\frac1nh^{\mathrm{post}}_l\mathbf{1}$. Then \eqref{eq:hc} is equivalent to the two recursions
\begin{equation}\label{eq:two-channel}
\bar x_{l+1}^{\!\top}=\bar x_l^{\!\top}+\bar h_l\,u_l,\qquad
x^{\perp}_{l+1}=H_l\,x^{\perp}_l+Q(h^{\mathrm{post}}_l)^{\!\top} u_l .
\end{equation}
The Jacobian of the residual path $x_l\mapsto x_L$, with all block outputs held fixed, is the map $x\mapsto H_{L:l}\,x$, and its adjoint is $y\mapsto H_{L:l}^{\!\top} y$. Both maps fix $\mathbf{1}$. Thus the gain of the mean channel is exactly one in both directions, for all mixers in $\mathcal{B}_n$.

\label{cor:fading}
Let $\rho_i:=\sigma_2(H_i)$ and $\rho_{L:l}:=\prod_{i=l}^{L-1}\rho_i$. Then for $l<L$,
\begin{equation}\label{eq:fading}
\|x^{\perp}_L\|_F\le\rho_{L:l}\|x^{\perp}_l\|_F+\sum_{i=l}^{L-1}\rho_{L:i+1}\|Q(h^{\mathrm{post}}_i)^{\!\top}\|_2\|u_i\|_2 .
\end{equation}
For the backward map, $\|QH_{L:l}^{\!\top} y\|_F\le\rho_{L:l}\|Qy\|_F$. If $\rho_i\le\rho<1$ for all $i$, then $\rho^{k}\le e^{-k/\tau}$ with the \emph{horizon}
\begin{equation}\label{eq:horizon}
\tau:=1/(1-\rho).
\end{equation}

\label{lem:differential}
Let $H=\Phi(W)$, and define $A_H:\mathbb{R}^{n\times n}\to\mathcal{T}$ by $A_H(\xi):=\Pi_H(H\odot\xi)$.
\begin{enumerate}[leftmargin=1.4em,itemsep=0pt,topsep=1pt,label=(\alph*)]
\item $\mathrm{d}\Phi_W(V)=A_H(V)$ for every $V\in\mathbb{R}^{n\times n}$.
\item $A_H$ is self-adjoint and positive semidefinite, with kernel $\mathfrak{s}$. On $\mathcal{T}$ it is the inverse of the Fisher--Rao metric tensor: $g_H(\xi,\zeta)=\langle A_H^{-1}\xi,\zeta\rangle$ for $\xi,\zeta\in\mathcal{T}$.
\item For every differentiable $f$,
\begin{equation}\label{eq:logit-grad}
\nabla_W(f\circ\Phi)(W)=A_H\big(\nabla f(H)\big)=\operatorname{grad} f(H).
\end{equation}
\end{enumerate}

\label{thm:induced}
Let $f$ be $C^1$, and let $H(t)=\Phi(W(t))$.
\begin{enumerate}[leftmargin=1.4em,itemsep=1pt,topsep=1pt,label=(\alph*)]
\item \textup{(Logit gradient flow.)} If $\dot W=-\nabla_W(f\circ\Phi)(W)$, then $\dot H=-A_H^{2}\,\nabla f(H)$. This flow is the Riemannian gradient flow of $f$ for the \emph{squared Fisher--Rao metric} $\mathcal G_H(\xi,\zeta):=\langle A_H^{-1}\xi,A_H^{-1}\zeta\rangle$ on $\mathcal{T}$.
\item \textup{(Straight-through flow.)} If $\dot W=-\nabla f(\Phi(W))$, then $\dot H=-\operatorname{grad} f(H)$. This flow is the Fisher--Rao gradient flow, and it is also the entropic mirror flow $\frac{\mathrm{d}}{\mathrm{d} t}\log H\in-\nabla f(H)+\mathfrak{s}$.
\item \textup{(Three-way identity.)} Let $\eta>0$, $H^{(k)}=\Phi(W^{(k)})$, $\Gamma^{(k)}:=\nabla f(H^{(k)})$, and $W^{(k+1)}=W^{(k)}-\eta\Gamma^{(k)}$. Then
\begin{align}
H^{(k+1)}&=\mathrm{SK}\big(H^{(k)}\odot e^{-\eta\Gamma^{(k)}}\big)\notag\\
&=\operatorname*{arg\,min}_{H\in\mathcal{B}_n}\big\{\eta\langle \Gamma^{(k)},H\rangle+\operatorname{KL}(H\,\|\,H^{(k)})\big\}\notag\\
&=R_{H^{(k)}}\big(-\eta\,\operatorname{grad} f(H^{(k)})\big),\label{eq:three-way}
\end{align}
where $R_H(\xi):=\mathrm{SK}(H\odot\exp(\xi\oslash H))$ is the Sinkhorn retraction of \citet{douik2019manifold}.
\end{enumerate}

\label{rem:simplex}
For one row, that is, for the simplex with $p=\mathrm{softmax}(w)$, the analogue of $A_H$ is $A_p=\operatorname{diag}(p)-pp^{\!	op}$, the inverse Fisher--Rao tensor. The straight-through flow $\dot w=-
abla f(p)$ gives $\dot p=-A_p
abla f(p)$. This is the replicator equation, which is the Fisher--Rao gradient flow \citep{shahshahani1979new,hofbauer1998evolutionary}. The exact logit flow gives $\dot p=-A_p^{2}
abla f(p)$. Theorem~ef{thm:induced} is the doubly stochastic version of this pair of flows. The gauge $\mathfrak{s}$ takes the place of the single normalizing constant.

\label{lem:additive}
Let $\omega\in\mathbb{R}^{n\times n}_{>0}$ and $C\in\mathbb{R}^{n\times n}$. The problem
\[
\min_{a,b\in\mathbb{R}^n}\ \sum_{i,j}\omega_{ij}\,(C_{ij}-a_i-b_j)^2
\]
has a minimizer, and its fitted values $m_{ij}:=a_i+b_j$ are unique. They satisfy
\begin{equation}\label{eq:additive}
\|m\|_\infty\le(2n-1)\,\|C\|_\infty .
\end{equation}
The constant $2n-1$ is sharp.

\label{lem:small-grad}
Let $H\in\mathcal{B}_n^{\circ}$ and $G:=\|\nabla f(H)\|_\infty$. Then $|\operatorname{grad} f(H)_{ij}|\le 2nG\,H_{ij}$ for all $(i,j)$, and $\|\operatorname{grad} f(H)\|_\infty\le 2n(n-1)\,G\,\varepsilon(H)$. Consequently, for every $W$ and $H=\Phi(W)$,
\begin{equation}\label{eq:flat}
\|\nabla_W(f\circ\Phi)(W)\|_\infty\le 2n(n-1)\,\|\nabla f(H)\|_\infty\,\varepsilon(H).
\end{equation}

\label{thm:viscosity}
Let $W(t)$, $t\in[0,T)$, solve $\dot W=-\nabla_W(f\circ\Phi)(W)$, let $H(t)=\Phi(W(t))$, and let $G:=\sup_{t<T}\|\nabla f(H(t))\|_\infty<\infty$. Then for all $i,j$ and $t$,
\begin{equation}\label{eq:viscosity}
\Big|\frac{\mathrm{d}}{\mathrm{d} t}\log H_{ij}(t)\Big|\ \le\ 4n^{3}\,G\,\varepsilon(H(t)).
\end{equation}
Let $\varepsilon_0:=\varepsilon(H(0))$ and $c:=4n^3G$. Then
\begin{align}
\varepsilon(H(t))&\ge\frac{\varepsilon_0}{1+c\,\varepsilon_0\,t}\quad\text{for } t<T,\label{eq:approach}\\
\varepsilon(H(t))&\le\frac{\varepsilon_0}{1-c\,\varepsilon_0\,t}\quad\text{for } t<T,\ t<\tfrac{1}{c\varepsilon_0}.\label{eq:escape}
\end{align}
Thus the flow needs time at least $(1/\varepsilon-1/\varepsilon_0)/c$ to reach a proximity $\varepsilon<\varepsilon_0$, and time at least $1/(2c\,\varepsilon_0)$ to double the proximity.

\label{thm:fr-rate}
Let $H(t)$ solve $\dot H=-\operatorname{grad} f(H)$, and let $G$ be as above. Then $|\frac{\mathrm{d}}{\mathrm{d} t}\log H_{ij}(t)|\le 2nG$, and therefore
\begin{equation}\label{eq:fr-bounds}
\varepsilon_0\,e^{-2nGt}\ \le\ \varepsilon(H(t))\ \le\ \varepsilon_0\,e^{2nGt}.
\end{equation}
The loss $f_\pi(H):=-\langle P_\pi,H\rangle$ (thus $G=1$) attains the exponential rate: for every start $H(0)=\Phi(W_0)$,
\begin{equation}\label{eq:fr-attained}
\varepsilon(H(t))\le(n-1)^{n-1}\,e^{2\|W_0\|_\infty}\,e^{-t}\quad\text{for all } t\ge0.
\end{equation}
For the same loss and start, the logit gradient flow satisfies \eqref{eq:approach} with $c=4n^3$.

\label{prop:n2}
Let $n=2$ and $w:=W_{11}+W_{22}-W_{12}-W_{21}$. Then $\Phi(W)=\begin{psmallmatrix}p&q\\q&p\end{psmallmatrix}$ with $q=1-p$ and $\log\frac pq=\frac w2$, and $q=\varepsilon(\Phi(W))$ if $p\ge\frac12$. For $f(H)=\langle C,H\rangle$, let $\Delta:=C_{12}+C_{21}-C_{11}-C_{22}$; thus $\Delta>0$ means that $I$ is the optimal vertex. Then
\begin{equation}\label{eq:n2}
\begin{aligned}
\text{Fisher--Rao:}\ \ &\dot w=\Delta, & \dot q&=-\tfrac{\Delta}{2}\,q(1-q),\\
\text{logit:}\ \ &\dot w=2\Delta pq, & \dot q&=-\Delta\,q^{2}(1-q)^{2}.
\end{aligned}
\end{equation}
For $\Delta<0$, the logit flow satisfies $q(t)\le q_0/(1-|\Delta|q_0t)$.

\label{prop:knight}
Let $\nu=\nu^\star\odot(\mathbf{1}+v)$. Then
\[
\Psi(\nu)=\nu^\star\odot\big(\mathbf{1}+H^{\!\top} Hv+O(\|v\|^2)\big),
\]
and the column sums of $\operatorname{diag}(\mu(\nu))K\operatorname{diag}(\nu)$ are $\mathbf{1}+(I-H^{\!\top} H)v+O(\|v\|^2)$. On $\mathbf{1}^\perp$ the map $H^{\!\top} H$ is symmetric with norm $\sigma_2(H)^2$. Thus, in the linearized iteration $v_k=(H^{\!\top} H)^kv_0$, the column-sum error $r_k:=\|(I-H^{\!\top} H)v_k\|_\infty$ satisfies $r_k\le\sigma_2(H)^{2k}\|Qv_0\|_2$. This bound is tight if $Qv_0$ has a component along a top singular vector of $HQ$ \citep{knight2008sinkhorn}. With the horizon $\tau=1/(1-\sigma_2(H))$,
\begin{equation}\label{eq:sweeps-per-efold}
e^{-2k/(\tau-1)}\ \le\ \sigma_2(H)^{2k}\ \le\ e^{-2k/\tau}.
\end{equation}

\label{rem:hilbert}
The Sinkhorn map contracts Hilbert's projective metric, and this fact gives a global, non-asymptotic bound. Each half-sweep multiplies the projective distance between scaling vectors by at most Birkhoff's coefficient $\kappa(K)=(\sqrt{\theta(K)}-1)/(\sqrt{\theta(K)}+1)$ \citep{birkhoff1957extensions}. Here $\theta(K)=\max_{i,j,k,l}K_{ik}K_{jl}/(K_{jk}K_{il})$ is the largest cross-ratio. \citet{franklin1989scaling} use this fact to prove linear convergence of Sinkhorn--Knopp in that metric \citep[Theorems~4.1--4.2]{peyre2019computational}. For $K=\exp W$ with $\|W\|_\infty\le M$ we have $\theta(K)\le e^{4M}$, and therefore
\begin{equation}\label{eq:tanh}
\kappa(K)\le\frac{e^{2M}-1}{e^{2M}+1}=\tanh M .
\end{equation}
This is a worst-case factor of $\tanh(M)^2$ per sweep. Sharp logits (large $M$) are necessary to reach mixers near the vertices, because $1-\sigma_2\ge e^{-4M}$ by Theorem~\ref{thm:contraction}(d). By \eqref{eq:tanh}, the same sharpness slows the projection in the worst case: $1-\tanh(M)^2\approx4e^{-2M}$. For random logits the truncation error is much smaller than this worst case (Figure~\ref{fig:sinkhorn}). The local law of Proposition~\ref{prop:knight} is the relevant one, and it is tight.

\label{rem:ohc}
The orthogonal hyper-connections of \citet{guo2026ohc} use mixers in $SO(n)$ that do not fix $\mathbf{1}$. The authors identify the mean-preserving subgroup $\{A\in SO(n):A\mathbf{1}=\mathbf{1}\}\cong SO(n-1)$. With an intervention experiment, they argue that the value of $SO(n)$ is the coupling between the mean and the differences that this subgroup forbids. Theorem~\ref{thm:two-channel} makes the trade explicit.

In the basis $[\mathbf{1}/\sqrt n,\ U]$, a general orthogonal mixer has off-diagonal blocks that rotate the mean into the differences and back. Thus the stream mean is no longer a residual network with unit gain. Instead the whole stream obeys a \emph{rotated} identity map, $x_L=H_{L:l}x_l+\sum_iH_{L:i+1}(h^{\mathrm{post}}_i)^{\!\top} u_i$ with $H_{L:l}$ orthogonal. No norm is lost in either direction. But mHC restores one property: the mean signal of layer $l$ reaches layer $L$ unchanged. Under a general orthogonal mixer, this property holds only up to an orthogonal change of coordinates. It is an empirical question if this property is worth its cost. The evidence of \citet{guo2026ohc} favors the coupled version. By Proposition~\ref{prop:rigidity}, the question does not arise for nonnegative designs, because their only collapse-free mixers are the permutations.

\label{aux:sinkhorn}
Let $K\in\mathbb{R}^{n\times n}$ have positive entries \citep{sinkhorn1964relationship,sinkhorn1967concerning}.
\begin{enumerate}[leftmargin=1.6em,itemsep=1pt,label=(\alph*)]
\item There are positive diagonal matrices $D_1,D_2$ such that $D_1KD_2$ is doubly stochastic. The matrix $D_1KD_2$ is unique, and the pair $(D_1,D_2)$ is unique up to $(sD_1,s^{-1}D_2)$ with $s>0$.
\item The alternating normalization of rows and columns, started at $K$, converges to $D_1KD_2$.
\end{enumerate}

\label{aux:pf}
Let $N\in\mathbb{R}^{n\times n}$ be nonnegative.
\begin{enumerate}[leftmargin=1.6em,itemsep=1pt,label=(\alph*)]
\item If $N$ is irreducible, then its spectral radius is a simple eigenvalue \citep[Chapter~1]{seneta1981nonnegative}, \citep[Chapter~8]{horn2013matrix}.
\item If $N$ is symmetric and reducible, then there is a nonempty proper subset $\mathcal S\subset[n]$ with $N_{jk}=0$ for all $j\in\mathcal S$ and $k\notin\mathcal S$. (A matrix is reducible if a simultaneous permutation of its rows and columns gives a block upper triangular form. For a symmetric matrix the off-diagonal block is then zero.)
\end{enumerate}

\begin{steps}
\item[{\color{refcool}\ensuremath{\langle1\rangle}1}.] $\operatorname{conv} O(m)$ is a subset of the ball.
\par{\sffamily\small\color{muted}Proof:}\  Orthogonal matrices have norm one, and the ball is convex.
\item[{\color{refcool}\ensuremath{\langle1\rangle}2}.] {\sffamily\small\color{navy}Assume:}\  $\|B\|_2\le1$. {\sffamily\small\color{navy}Prove:}\  $B\in\operatorname{conv} O(m)$.
\par{\sffamily\small\color{muted}Proof:}\  Write $B=V\Sigma Z^{\!\top}$ with $V,Z\in O(m)$ and $\Sigma=\operatorname{diag}(\sigma_1,\dots,\sigma_m)$, $\sigma_i\in[0,1]$. For a sign vector $s\in\{\pm1\}^m$, let $\lambda_s:=\prod_i\frac{1+s_i\sigma_i}{2}\ge0$. Then $\sum_s\lambda_s=1$ and $\sum_s\lambda_s\,s_i=\sigma_i$ for every $i$. Thus $\Sigma=\sum_s\lambda_s\operatorname{diag}(s)$, and $B=\sum_s\lambda_s\,V\operatorname{diag}(s)Z^{\!\top}$ is a convex combination of orthogonal matrices.
\item[{\color{refcool}\ensuremath{\langle1\rangle}3}.]{\sffamily\small\color{navy}Q.E.D.}
\par{\sffamily\small\color{muted}Proof:}\  By {\color{refcool}\ensuremath{\langle1\rangle}1} and {\color{refcool}\ensuremath{\langle1\rangle}2}.
\end{steps}

\begin{steps}
\item[{\color{refcool}\ensuremath{\langle1\rangle}1}.] $H=J/n+QHQ$.
\par{\sffamily\small\color{muted}Proof:}\  By (F3), $HJ=J$ and $HQ=QH$. Thus $H=H(J/n+Q)=J/n+HQ$, and $HQ=HQ^2=QHQ$.
\item[{\color{refcool}\ensuremath{\langle1\rangle}2}.] $\mathbb{R}\mathbf{1}$ and $\mathbf{1}^\perp$ are invariant under $H$ and $H^{\!\top}$.
\par{\sffamily\small\color{muted}Proof:}\  $H\mathbf{1}=\mathbf{1}$. For $x\perp\mathbf{1}$, $\langle Hx,\mathbf{1}\rangle=\langle x,H^{\!\top}\mathbf{1}\rangle=\langle x,\mathbf{1}\rangle=0$. The same argument applies to $H^{\!\top}\in\mathcal{B}_n$.
\item[{\color{refcool}\ensuremath{\langle1\rangle}3}.] The singular values of $H$ are $1$ and the singular values $s_1\ge\dots\ge s_{n-1}$ of $U^{\!\top} HU$, with $\sigma_{k+1}(H)=s_k$.
\par{\sffamily\small\color{muted}Proof:}\  By {\color{refcool}\ensuremath{\langle1\rangle}2}, $H$ has the stated block form, and a block diagonal matrix has the singular values of its blocks. By (F1), $s_1\le\|H\|_2\le1$, so the largest singular value is the block $1$.
\item[{\color{refcool}\ensuremath{\langle1\rangle}4}.]{\sffamily\small\color{navy}Q.E.D.}
\par{\sffamily\small\color{muted}Proof:}\  Steps {\color{refcool}\ensuremath{\langle1\rangle}1}--{\color{refcool}\ensuremath{\langle1\rangle}3} give all claims, because $|\det(U^{\!\top} HU)|=\prod_ks_k$. By (F2), products of doubly stochastic matrices are doubly stochastic.
\end{steps}

\begin{steps}
\item[{\color{refcool}\ensuremath{\langle1\rangle}1}.] The claim holds for $\varepsilon_\pi$.
\par{\sffamily\small\color{muted}Proof:}\  $\varepsilon_\pi$ is the maximum of the entries on a fixed set of cells, and a maximum is monotone and positively homogeneous.
\item[{\color{refcool}\ensuremath{\langle1\rangle}2}.]{\sffamily\small\color{navy}Q.E.D.}
\par{\sffamily\small\color{muted}Proof:}\  $\varepsilon=\min_\pi\varepsilon_\pi$ is a minimum of finitely many functions with the two properties of {\color{refcool}\ensuremath{\langle1\rangle}1}, and a minimum keeps both properties.
\end{steps}

\begin{steps}
\item[{\color{refcool}\ensuremath{\langle1\rangle}1}.] {\sffamily\small\color{navy}Let:}\  $z:=(a_1,\dots,a_n,b_1,\dots,b_{n-1})\in\mathbb{R}^{2n-1}$, with the gauge $b_n:=0$. {\sffamily\small\color{navy}Let:}\  $X\in\mathbb{R}^{n^2\times(2n-1)}$ be the design matrix: the row of the cell $(i,j)$ has the entry $1$ in the columns of $a_i$ and $b_j$ (only in the column of $a_i$ if $j=n$), and $0$ elsewhere. {\sffamily\small\color{navy}Let:}\  $y:=\mathrm{vec}\,C$ and $D:=\operatorname{diag}(\omega)$. Then $(Xz)_{ij}=a_i+b_j$, and the problem is $\min_z\|D^{1/2}(y-Xz)\|_2^2$.
\par{\sffamily\small\color{muted}Proof:}\  By the definitions. The gauge $b_n=0$ does not change the set of fitted values, because $(a+s\mathbf{1},b-s\mathbf{1})$ and $(a,b)$ have the same fitted values.
\item[{\color{refcool}\ensuremath{\langle1\rangle}2}.] $X$ has full column rank. Thus the minimizer $z^\star=(X^{\!\top} DX)^{-1}X^{\!\top} Dy$ is unique, and the fitted values $m=Xz^\star$ are unique.
\par{\sffamily\small\color{muted}Proof:}\  If $Xz=0$, then $a_i=-b_j$ for all $i,j$, so all $b_j$ are equal. Thus $b=0$ (because $b_n=0$), and $a=0$.
\item[{\color{refcool}\ensuremath{\langle1\rangle}3}.] $z^\star=\sum_{S}\lambda_S\,z_S$, where $S$ ranges over the $(2n-1)$-element sets of cells with $\det X_S\ne0$, $z_S$ solves $X_Sz=y_S$, and
\begin{equation}\label{eq:jacobi}
\lambda_S=\frac{\omega_S\det(X_S)^2}{\sum_{S'}\omega_{S'}\det(X_{S'})^2}\ge0,\qquad\sum_S\lambda_S=1 .
\end{equation}
\begin{steps}
\item[{\color{refcool}\ensuremath{\langle2\rangle}1}.] $z^\star_r=\det(X^{\!\top} DX^{(r)})/\det(X^{\!\top} DX)$, where $X^{(r)}$ is $X$ with its $r$-th column replaced by $y$.
\par{\sffamily\small\color{muted}Proof:}\  By Cramer's rule (Theorem~\ref{aux:cb}), $z^\star_r=\det(N_r)/\det(X^{\!\top} DX)$, where $N_r$ is $X^{\!\top} DX$ with its $r$-th column replaced by $X^{\!\top} Dy$. This column is the $r$-th column of $X^{\!\top} DX^{(r)}$, and the other columns agree, so $N_r=X^{\!\top} DX^{(r)}$.
\item[{\color{refcool}\ensuremath{\langle2\rangle}2}.] $\det(X^{\!\top} DX^{(r)})=\sum_S\omega_S\det(X_S)\det(X^{(r)}_S)$ and $\det(X^{\!\top} DX)=\sum_S\omega_S\det(X_S)^2$.
\par{\sffamily\small\color{muted}Proof:}\  The Cauchy--Binet formula (Theorem~\ref{aux:cb}).
