\par{\sffamily\small\color{muted}Proof:}\  For $S$ with $\det X_S\ne0$, Cramer's rule for $X_Sz=y_S$ gives $(z_S)_r=\det(X^{(r)}_S)/\det(X_S)$. Insert this into {\color{refcool}\ensuremath{\langle2\rangle}2}, and divide as in {\color{refcool}\ensuremath{\langle2\rangle}1}. (A representation of this kind is classical; see \citet{bental1990geometric}.)
\end{steps}
\item[{\color{refcool}\ensuremath{\langle1\rangle}4}.] $\det X_S\ne0$ if and only if the cells of $S$ form a spanning tree of the complete bipartite graph $K_{n,n}$.
\par{\sffamily\small\color{muted}Proof:}\  View each cell $(i,j)$ as the edge between the row vertex $i$ and the column vertex $j$ of $K_{n,n}$. This graph is connected and has $2n$ vertices. If we multiply the $b$-columns of $X$ by $-1$, then $X^{\!\top}$ becomes the signed incidence matrix of $K_{n,n}$ (edges oriented from rows to columns), without the row of the vertex $b_n$. This change multiplies each $\det X_S$ by $\pm1$. Apply Theorem~\ref{aux:tree}.
\item[{\color{refcool}\ensuremath{\langle1\rangle}5}.] For every spanning tree $S$ and every cell $(i,j)$, $|(Xz_S)_{ij}|\le(2n-1)\|C\|_\infty$.
\par{\sffamily\small\color{muted}Proof:}\  The unique path in $S$ from the row vertex $i$ to the column vertex $j$ alternates between rows and columns: $i=i_0,\ j_1,\ i_1,\ j_2,\ \dots,\ i_k,\ j_{k+1}=j$. Its edges are the cells $(i_r,j_{r+1})$ for $0\le r\le k$ and $(i_r,j_r)$ for $1\le r\le k$, and all of them are in $S$. Because $z_S$ interpolates $C$ on $S$, a telescoping sum gives
\begin{equation}\label{eq:path-sum}
a_i+b_j=\sum_{r=0}^{k}\big(a_{i_r}+b_{j_{r+1}}\big)-\sum_{r=1}^{k}\big(a_{i_r}+b_{j_r}\big)
=\sum_{r=0}^{k}C_{i_rj_{r+1}}-\sum_{r=1}^{k}C_{i_rj_r}.
\end{equation}
This is a signed sum of $2k+1$ entries of $C$. A path in a tree with $2n$ vertices has at most $2n-1$ edges, so $2k+1\le2n-1$.
\item[{\color{refcool}\ensuremath{\langle1\rangle}6}.] $\|m\|_\infty\le(2n-1)\|C\|_\infty$.
\par{\sffamily\small\color{muted}Proof:}\  By {\color{refcool}\ensuremath{\langle1\rangle}3} and {\color{refcool}\ensuremath{\langle1\rangle}4}, $m=Xz^\star=\sum_S\lambda_SXz_S$ is a convex combination over spanning trees. Apply {\color{refcool}\ensuremath{\langle1\rangle}5}.
\item[{\color{refcool}\ensuremath{\langle1\rangle}7}.] The constant $2n-1$ cannot be made smaller.
\par{\sffamily\small\color{muted}Proof:}\  Let $S_0$ be the Hamiltonian path $r_1,c_1,r_2,c_2,\dots,r_n,c_n$ through the row vertices $r_k$ and the column vertices $c_k$. Its cells are $(r_k,c_k)$ for $1\le k\le n$ and $(r_k,c_{k-1})$ for $2\le k\le n$; it is a spanning tree with $2n-1$ cells. Let $C=+1$ on the cells $(r_k,c_k)$, $C=-1$ on the cells $(r_k,c_{k-1})$, and $C=0$ elsewhere, so $\|C\|_\infty=1$. Let $\omega=1$ on $S_0$ and $\omega=\nu$ elsewhere. Every spanning tree other than $S_0$ has a cell of weight $\nu$, and $\det(X_S)^2=1$ for every tree. Thus $\lambda_{S_0}\to1$ in \eqref{eq:jacobi} as $\nu\to0$, and $m\to Xz_{S_0}$. By \eqref{eq:path-sum}, the fitted value of $z_{S_0}$ at the cell $(r_1,c_n)$ is the alternating sum along the whole path, $n\cdot(+1)-(n-1)\cdot(-1)=2n-1$.
