\par{\sffamily\small\color{muted}Proof:}\  Step {\color{refcool}\ensuremath{\langle1\rangle}2} gives existence and uniqueness, {\color{refcool}\ensuremath{\langle1\rangle}6} gives \eqref{eq:additive}, and {\color{refcool}\ensuremath{\langle1\rangle}7} gives sharpness.
\end{steps}

\begin{steps}
\item[{\color{refcool}\ensuremath{\langle1\rangle}1}.] $\prod_{l<L}\sigma_n(H_l)\ge c_0^{\,n-1}$.
\par{\sffamily\small\color{muted}Proof:}\  By Lemma~\ref{lem:two-block}, $|\det(U^{\!\top} H_lU)|=\prod_{k\ge2}\sigma_k(H_l)\le\sigma_n(H_l)$, because all singular values are in $[0,1]$. Also $|\det(U^{\!\top} H_{L:0}U)|\ge\sigma_n(H_{L:0})^{n-1}\ge c_0^{\,n-1}$. The subspace $\mathbf{1}^\perp$ is invariant under every $H_l$, so the determinant on $\mathbf{1}^\perp$ is multiplicative: $\det(U^{\!\top} H_{L:0}U)=\prod_l\det(U^{\!\top} H_lU)$.
\item[{\color{refcool}\ensuremath{\langle1\rangle}2}.] At least half of the layers satisfy $\vartheta_l:=1-\sigma_n(H_l)\le2(n-1)\log(1/c_0)/L$.
\par{\sffamily\small\color{muted}Proof:}\  Because $1-s\le\log(1/s)$ for $s\in(0,1]$, {\color{refcool}\ensuremath{\langle1\rangle}1} gives $\sum_l\vartheta_l\le\sum_l\log(1/\sigma_n(H_l))\le(n-1)\log(1/c_0)$. Apply Markov's inequality.
\item[{\color{refcool}\ensuremath{\langle1\rangle}3}.] These layers satisfy $\varepsilon(H_l)\le\varepsilon_\star$.
\par{\sffamily\small\color{muted}Proof:}\  For them, $4n\vartheta_l\le8n(n-1)\log(1/c_0)/L<1$. Proposition~\ref{prop:rigidity}(d) gives $\varepsilon(H_l)\le4n\vartheta_l\le\varepsilon_\star$.
\item[{\color{refcool}\ensuremath{\langle1\rangle}4}.]{\sffamily\small\color{navy}Q.E.D.}
\par{\sffamily\small\color{muted}Proof:}\  Step {\color{refcool}\ensuremath{\langle1\rangle}3} gives the first claim. Solve $\varepsilon_\star\ge\varepsilon_0/(1+c\varepsilon_0t)$ for $t$ in \eqref{eq:approach} for the first time bound. The bound \eqref{eq:fr-bounds} gives the second time bound, and Theorem~\ref{thm:fr-rate} shows that logarithmic time is possible.
\end{steps}

